def noisy(im, s):
    rng = np.random.default_rng(1)
    a = np.array(im, dtype=int) + rng.integers(-s, s + 1, (im.height, im.width))
    return Image.fromarray(np.clip(a, 0, 255).astype('uint8'))
for s in (0, 50, 90, 100, 105, 110):
    print(s, score(noisy(page(24), s)))

